using System;using System.IO;using System.Diagnostics;
class AerialCheck {
 static int count;static void Check(bool ok,string s){if(!ok)throw new Exception(s);count++;Console.WriteLine("PASS "+s);}static void Reject(Action a,string s){try{a();}catch{Check(true,s);return;}throw new Exception(s);}
 static int Main(string[] args){try{string root=args[0],json=File.ReadAllText(root+"/aerial-release.json"),version;Check(TV.AerialVariant(14)=="lite"&&TV.AerialVariant(19)=="lite","Android 4.x selects Lite");Check(TV.AerialVariant(21)=="standard"&&TV.AerialVariant(35)=="standard","Android 5+ selects standard");Reject(()=>TV.AerialVariant(13),"unsupported old Android rejected");foreach(string variant in new[]{"lite","standard","guard"}){var a=TV.ParseAerialAsset(json,variant,out version);TV.VerifyAerialFile(root+"/"+a.Name,a);Check(true,variant+" official asset SHA256 and size verified");var p=Process.Start(new ProcessStartInfo(args[1],"dump badging \""+root+"/"+a.Name+"\""){UseShellExecute=false,RedirectStandardOutput=true,CreateNoWindow=true});string dump=p.StandardOutput.ReadToEnd();p.WaitForExit();TV.CheckAerialMetadata(dump,variant,variant=="lite"?19:35,"arm64-v8a,armeabi-v7a");Check(true,variant+" real APK identity and SDK/ABI compatible");if(variant!="lite")Reject(()=>TV.CheckAerialMetadata(dump,variant,19,"arm64-v8a"),variant+" SDK mismatch rejected");Reject(()=>TV.CheckAerialMetadata(dump.Replace("app.orchard.tv","evil.app"),variant,35,"arm64-v8a"),variant+" wrong package rejected");}Reject(()=>{string v;TV.ParseAerialAsset(json.Replace("https://github.com/","https://evil.example/"),"standard",out v);},"foreign asset URL rejected");Reject(()=>{string v;TV.ParseAerialAsset(json.Replace("sha256:","bad:"),"standard",out v);},"missing SHA256 rejected");var asset=TV.ParseAerialAsset(json,"standard",out version);asset.Digest="sha256:"+new string('0',64);Reject(()=>TV.VerifyAerialFile(root+"/"+asset.Name,asset),"tampered SHA256 rejected");Console.WriteLine(count+" Aerial checks passed (no physical TV)");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
